package com.codeforge.platform.config;

import com.codeforge.platform.entity.OrgMember;
import com.codeforge.platform.entity.Organization;
import com.codeforge.platform.entity.User;
import com.codeforge.platform.mapper.OrgMemberMapper;
import com.codeforge.platform.mapper.OrganizationMapper;
import com.codeforge.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final OrganizationMapper organizationMapper;
    private final OrgMemberMapper orgMemberMapper;
    private final PasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper,
                           OrganizationMapper organizationMapper,
                           OrgMemberMapper orgMemberMapper,
                           PasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.organizationMapper = organizationMapper;
        this.orgMemberMapper = orgMemberMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        if (userMapper.findByUsername("admin") != null) {
            return;
        }

        User admin = new User();
        admin.setUsername("admin");
        admin.setPassword(passwordEncoder.encode("admin123"));
        admin.setRole("ADMIN");
        admin.setCreatedAt(LocalDateTime.now());
        userMapper.insert(admin);

        User alice = new User();
        alice.setUsername("alice");
        alice.setPassword(passwordEncoder.encode("alice123"));
        alice.setRole("USER");
        alice.setCreatedAt(LocalDateTime.now());
        userMapper.insert(alice);

        Organization organization = new Organization();
        organization.setName("默认团队");
        organization.setDescription("系统默认团队");
        organization.setOwnerId(admin.getId());
        organization.setCreatedAt(LocalDateTime.now());
        organizationMapper.insert(organization);

        OrgMember member = new OrgMember();
        member.setOrgId(organization.getId());
        member.setUserId(admin.getId());
        member.setMemberRole("ADMIN");
        member.setJoinedAt(LocalDateTime.now());
        orgMemberMapper.insert(member);
    }
}

package com.codeforge.platform.config;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.JwtBuilder;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.security.Key;
import java.util.Date;

@Component
public class JwtUtil {

    @Value("${jwt.secret}")
    private String secret;

    @Value("${jwt.expiration}")
    private Long expiration;

    private Key getSigningKey() {
        return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    }

    public String generateToken(String username, String role, Long userId) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + expiration);
        JwtBuilder builder = Jwts.builder();
        invokeFirst(builder, new String[]{"setSubject", "subject"},
                new Class<?>[]{String.class}, username);
        builder.claim("role", role);
        builder.claim("userId", userId);
        invokeFirst(builder, new String[]{"setIssuedAt", "issuedAt"},
                new Class<?>[]{Date.class}, now);
        invokeFirst(builder, new String[]{"setExpiration", "expiration"},
                new Class<?>[]{Date.class}, expiry);
        return builder.signWith(getSigningKey(), SignatureAlgorithm.HS256).compact();
    }

    public boolean validateToken(String token) {
        try {
            parseClaims(token);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public String getUsername(String token) {
        return parseClaims(token).getSubject();
    }

    public String getRole(String token) {
        Object role = parseClaims(token).get("role");
        return role == null ? null : String.valueOf(role);
    }

    public Long getUserId(String token) {
        Object userId = parseClaims(token).get("userId");
        if (userId instanceof Number number) {
            return number.longValue();
        }
        return userId == null ? null : Long.valueOf(String.valueOf(userId));
    }

    private Claims parseClaims(String token) {
        Object parserBuilder = newParserBuilder();
        invokeFirst(parserBuilder, new String[]{"setSigningKey"},
                new Class<?>[]{Key.class}, getSigningKey());
        Object parser = invokeFirst(parserBuilder, new String[]{"build"}, new Class<?>[0]);
        Object jws;
        try {
            jws = invokeFirst(parser, new String[]{"parseClaimsJws", "parseSignedClaims"},
                    new Class<?>[]{CharSequence.class}, token);
        } catch (IllegalStateException e) {
            jws = invokeFirst(parser, new String[]{"parseClaimsJws", "parseSignedClaims"},
                    new Class<?>[]{String.class}, token);
        }
        return (Claims) invokeFirst(jws, new String[]{"getBody", "getPayload"}, new Class<?>[0]);
    }

    private Object newParserBuilder() {
        for (String name : new String[]{"parserBuilder", "parser"}) {
            try {
                Method method = Jwts.class.getMethod(name);
                return method.invoke(null);
            } catch (NoSuchMethodException ignored) {
                // try the next factory name
            } catch (Exception e) {
                throw new IllegalStateException("Unable to create JWT parser builder", e);
            }
        }
        throw new IllegalStateException("No JWT parser builder factory found on io.jsonwebtoken.Jwts");
    }

    private Object invokeFirst(Object target, String[] names, Class<?>[] signature, Object... args) {
        for (String name : names) {
            try {
                Method method = target.getClass().getMethod(name, signature);
                return method.invoke(target, args);
            } catch (NoSuchMethodException ignored) {
                // try the next candidate name
            } catch (Exception e) {
                Throwable cause = e instanceof java.lang.reflect.InvocationTargetException && e.getCause() != null
                        ? e.getCause() : e;
                if (cause instanceof RuntimeException runtimeException) {
                    throw runtimeException;
                }
                throw new IllegalStateException("Failed to invoke " + name + " on " + target.getClass(), cause);
            }
        }
        throw new IllegalStateException("None of " + String.join("/", names) + " found on " + target.getClass());
    }
}

package com.codeforge.platform.config;

import com.codeforge.platform.filter.JwtAuthFilter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthFilter jwtAuthFilter;

    public SecurityConfig(JwtAuthFilter jwtAuthFilter) {
        this.jwtAuthFilter = jwtAuthFilter;
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session ->
                        session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/login", "/api/repos/*/readme").permitAll()
                        .anyRequest().authenticated())
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }
}

package com.codeforge.platform.controller;

import com.codeforge.platform.dto.ApiResponse;
import com.codeforge.platform.dto.LoginRequest;
import com.codeforge.platform.dto.LoginResponse;
import com.codeforge.platform.service.AuthService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<ApiResponse<LoginResponse>> login(@RequestBody LoginRequest request) {
        return ResponseEntity.ok(authService.login(request.getUsername(), request.getPassword()));
    }
}

package com.codeforge.platform.controller;

import com.codeforge.platform.dto.ApiResponse;
import com.codeforge.platform.dto.CreateFileRequest;
import com.codeforge.platform.service.RepoService;
import org.springframework.http.ResponseEntity;
