package com.codeforge.platform.controller;

import com.codeforge.platform.dto.ApiResponse;
import com.codeforge.platform.dto.CreateRepoRequest;
import com.codeforge.platform.entity.Repository;
import com.codeforge.platform.service.RepoService;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/repos")
public class RepoController {

    private final RepoService repoService;

    public RepoController(RepoService repoService) {
        this.repoService = repoService;
    }

    @PostMapping
    public ResponseEntity<ApiResponse<Repository>> createRepo(@RequestBody CreateRepoRequest request,
                                                              Authentication authentication) {
        Long userId = (Long) authentication.getPrincipal();
        return ResponseEntity.ok(repoService.createRepo(request, userId));
    }

    @GetMapping
    public ResponseEntity<ApiResponse<List<Repository>>> listRepos(
            @RequestParam(value = "orgId", required = false) Long orgId) {
        return ResponseEntity.ok(repoService.listRepos(orgId));
    }

    @GetMapping("/{repoId}")
    public ResponseEntity<ApiResponse<Map<String, Object>>> getRepo(@PathVariable("repoId") Long repoId) {
        return ResponseEntity.ok(repoService.getRepoDetail(repoId));
    }

    @GetMapping(value = "/{repoId}/readme", produces = "text/html;charset=UTF-8")
    public ResponseEntity<String> getReadme(@PathVariable("repoId") Long repoId) {
        return ResponseEntity.ok()
                .contentType(MediaType.parseMediaType("text/html;charset=UTF-8"))
                .body(repoService.getReadmeHtml(repoId));
    }
}

